    v = if value_flag, do: 1, else: 0
    scratch = scratch ||| v <<< 5
    data = <<>>

    {data, scratch, scratch_bits} =
      if value_flag do
        n = length(value.items)

        if n > 3 do
          raise ArgumentError, "value.items count is above the wire maximum"
        end

        v = n
        scratch = scratch ||| v <<< 6
        data = <<data::binary, scratch::little-size(1)-unit(8)>>
