            if 5 > num_bits, do: throw(:invalid)
            rv = rd(data, 2, 3)
            v = rv
            v_narrow_n = v
            v_narrow = %Example.Narrow{n: v_narrow_n}
            bits_read = 5
            {bits_read, {:narrow, v_narrow}}

