            if 39 > num_bits, do: throw(:invalid)
            rv = rdw(data, 2, 37)
            v = rv &&& 0xFFFFFFFF
            w = v
            v = rv >>> 32
            w = w ||| v <<< 32
            v_wide_w = w
            v_wide = %Example.Wide{w: v_wide_w}
            bits_read = 39
            {bits_read, {:wide, v_wide}}

          _ ->
            # None — the tag is the whole wire (SPEC §4.8)
            {bits_read, nil}
        end

