      case value_u do
        {:narrow, value_u_narrow} ->
          v = value_u_narrow.n &&& 0x7
          scratch = scratch ||| v <<< 7
          data = <<data::binary, scratch::little-size(1)-unit(8)>>
          scratch = scratch >>> 8
          scratch_bits = 2
