  @doc """
  Packs a RegainAfterAlign into a fresh binary and returns the wire bytes. The
  writer trusts the caller up to the O(1) contract checks, which raise
  ArgumentError — always on, since the BEAM has no compile-out assert.
  """
  @spec write_regain_after_align!(Example.RegainAfterAlign.t()) :: binary()
  def write_regain_after_align!(value) do
    %{
      lead: value_lead,
      items: value_items,
      s: value_s,
      p: value_p,
      q: value_q,
      r: value_r,
      tail: value_tail
    } = value

    v = value_lead &&& 0x1F
    scratch = v
    n = length(value_items)

    if n > 3 do
      raise ArgumentError, "value.items count is above the wire maximum"
    end

    v = n
    scratch = scratch ||| v <<< 5
    scratch_bits = 7

    {data, scratch, scratch_bits} =
      w_regain_after_align_items(value_items, <<>>, scratch, scratch_bits)

    if byte_size(value_s) > 4 do
      raise ArgumentError, "value.s longer than the declared 4-byte bound"
    end

    v = byte_size(value_s)
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 3
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    # align: zero-pad to the byte boundary (SPEC §4.3)
    data = if scratch_bits != 0, do: <<data::binary, scratch>>, else: data
    # the used bytes ride whole — the stream is byte-aligned here
    data = <<data::binary, value_s::binary>>
    v = value_p &&& 0xFFFFFFFF
    scratch = v
    v = value_q &&& 0x1FFFFFFF
    sc0 = scratch
    scratch = v
    v = value_r &&& 0x7FFFF
    scratch = scratch ||| v <<< 29
    v = value_tail &&& 0xF
    scratch = scratch ||| v <<< 48
    data = <<data::binary, sc0::little-size(4)-unit(8), scratch::little-size(6)-unit(8)>>
    scratch = scratch >>> 48
    # the residual byte, statically known to be there
    <<data::binary, scratch>>
  end

